// wmcpn002-mint-telegram (PRO-122)
// POST body: { request_id } from MCP gateway. Loads matching intent from
// /miru-data/mcp_gateway_pending_writes.jsonl, mints HMAC buttons, appends
// pending_callbacks intent (button_set=mcp_n8n_write), builds sendMessage body.
const fs = require('fs');
const crypto = require('crypto');
const MCP = '/miru-data/mcp_gateway_pending_writes.jsonl';
const PENDING = '/miru-data/pending_callbacks.jsonl';
const ANCHOR_UNIX = 1767225600;

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

const body = $input.item.json.body || $input.item.json;
const request_id = body.request_id || body.requestId;
if (!request_id) {
  throw new Error('request_id required in JSON body');
}

let content = '';
if (fs.existsSync(MCP)) content = fs.readFileSync(MCP, 'utf8');
const lines = content.split(String.fromCharCode(10)).filter(Boolean);
let row = null;
for (let i = lines.length - 1; i >= 0; i--) {
  let r;
  try { r = JSON.parse(lines[i]); } catch (e) { continue; }
  if (r.kind === 'intent' && r.request_id === request_id) {
    row = r;
    break;
  }
}
if (!row) {
  throw new Error('no intent row for request_id: ' + request_id);
}

const secret = $env.TELEGRAM_CALLBACK_SECRET;
const chatId = $env.TELEGRAM_CHAT_ID;
if (!secret) throw new Error('TELEGRAM_CALLBACK_SECRET not set');
if (!chatId) throw new Error('TELEGRAM_CHAT_ID not set');

const token = crypto.randomBytes(8).toString('hex').slice(0, 12);
const ts_minutes = Math.floor((Math.floor(Date.now() / 1000) - ANCHOR_UNIX) / 60);
const ts_hex = ts_minutes.toString(16).padStart(8, '0').slice(-8);

function buttonFor(actionCode, label) {
  const nonce = crypto.randomBytes(4).toString('hex');
  const payload = token + actionCode + nonce + ts_hex;
  const hmac = crypto.createHmac('sha256', secret).update(payload).digest('hex').slice(0, 32);
  const cb = token + actionCode + nonce + ts_hex + hmac;
  if (cb.length !== 61) throw new Error('callback_data length mismatch: ' + cb.length);
  return { text: label, callback_data: cb };
}

const button_set = 'mcp_n8n_write';
const inline_keyboard = [[buttonFor('a', 'Approve'), buttonFor('t', 'Triage')]];

const intentRow = {
  kind: 'intent',
  token,
  intent_written_at: new Date().toISOString(),
  trace_id: request_id,
  issue_id: null,
  issue_identifier: null,
  chosen_worker: null,
  confidence: null,
  risk: null,
  button_set,
  issue_existing_label_ids: [],
  labels_map: {}
};
fs.appendFileSync(PENDING, JSON.stringify(intentRow) + String.fromCharCode(10));

const op = row.operation || '?';
const wfName = (row.workflow_json && row.workflow_json.name) ? row.workflow_json.name : '(unnamed)';
const text = '<b>MCP n8n write approval</b>' + String.fromCharCode(10)
  + 'Operation: <code>' + esc(op) + '</code>' + String.fromCharCode(10)
  + 'Workflow: ' + esc(wfName) + String.fromCharCode(10)
  + 'request_id: <code>' + esc(request_id) + '</code>' + String.fromCharCode(10)
  + String.fromCharCode(10) + 'Choose:';

const telegram_send_body = {
  chat_id: chatId,
  text,
  parse_mode: 'HTML',
  reply_markup: { inline_keyboard }
};

return { json: { request_id, callback_token: token, telegram_send_body } };
